+//! A small cache of parsed templates keyed by their source text.
+
+use std::collections::hash_map::Entry;
+use std::collections::HashMap;
+
+use crate::engine::{Template, TemplateError};
+
+/// Caches parsed templates so repeated renders skip tokenizing.
+#[derive(Debug, Default)]
+pub struct TemplateCache {
+    entries: HashMap<String, Template>,
+    hits: u64,
+    misses: u64,
+}
+
+impl TemplateCache {
+    pub fn new() -> Self {
+        Self::default()
+    }
+
+    /// Returns the parsed template for `source`, parsing it on first use.
+    pub fn get_or_parse(&mut self, source: &str) -> Result<&Template, TemplateError> {
+        match self.entries.entry(source.to_string()) {
+            Entry::Occupied(entry) => {
+                self.hits += 1;
+                Ok(entry.into_mut())
+            }
+            Entry::Vacant(entry) => {
+                self.misses += 1;
+                Ok(entry.insert(Template::parse(source)?))
+            }
+        }
+    }
+
+    /// Fraction of lookups served from the cache, or `None` before the first lookup.
+    pub fn hit_rate(&self) -> Option<f64> {
+        let total = self.hits + self.misses;
+        (total > 0).then(|| self.hits as f64 / total as f64)
+    }
+
+    /// Drops every cached template and resets the hit statistics.
+    pub fn clear(&mut self) {
+        self.entries.clear();
+        self.hits = 0;
+        self.misses = 0;
+    }
+}
+
+#[cfg(test)]
+mod tests {
+    use super::*;
+
+    #[test]
+    fn reuses_parsed_templates() {
+        let mut cache = TemplateCache::new();
+        cache.get_or_parse("{{a}}").unwrap();
+        cache.get_or_parse("{{a}}").unwrap();
+        assert_eq!(cache.hit_rate(), Some(0.5));
+    }
+}

